    /// <para>제조사 원문 예제 (원문 철자·오타·표기 보존):</para>
    /// <code>
    /// ```csharp
    /// // C#에서의사용예
    /// [DllImport(“BlackfishNfcLib.dll", CallingConvention= CallingConvention.StdCall, CharSet=
    /// CharSet.Unicode)]
    /// public static extern int ReadResponseMessage([MarshalAs(UnmanagedType.LPWStr,
    /// SizeConst=512)] StringBuilder sResponse);
    /// // timer Tick 이벤트 처리 메서드에서 사용
    /// private void timer1_Tick(object sender, EventArgs e)
    /// {
    ///   StringBuilder sb= new StringBuilder(256);
    ///   Int iCount= ReadResponseMessage(sb);
    ///   if( iCount &gt; 0){ // 읽은메시지를여기에서처리 }
