    /// <example>
    /// 공개 제품 DLL로 한 장씩 두 번 요청하는 예입니다. 실제 용지 기준 위치를 먼저 준비하고, 이번 시험 용지에 맞는 배출 15mm를 사용합니다.
    /// 이 예제에는 using System 및 U2BIO.BT003PROLabelPrinting.dll 참조가 필요합니다. Wrapper를 직접 호출하거나 M/B를 중복 전송하지 않습니다.
    /// 서식의 규격·좌표·속도·농도는 이번 시험값이며 다른 매체에는 그 매체의 설정을 적용합니다.
    /// <code>
    /// string form = "^Q40,5,7.5+\r\n^W70\r\n^G0\r\n^S5\r\n^H19\r\n"
    ///     + "^P1\r\n^C1\r\n^R0\r\n^E15\r\n^L\r\n"
    ///     + "AW,80,120,10,1,0,0,^V00\r\n"
    ///     + "AW,80,160,10,1,0,0,^V01\r\nE\r\n";
    /// using (var printer = new U2BIO.BT003PROLabelPrinting.Bt003Printer())
    /// {
    ///     var connected = printer.ConnectUsb("0", 15);
    ///     if (!connected.IsSuccess)
    ///     {
    ///         Console.WriteLine("연결 실패: " + connected.Code);
    ///         return;
    ///     }
    ///     for (int number = 1; number &lt;= 2; number++)
    ///     {
    ///         var result = printer.Print(form, "DEMO " + number, "한글 변수 " + number);
    ///         // CP949 파일을 쓸 때의 동일한 요청: printer.PrintFile(formPath, firstValue, secondValue)
    ///         Console.WriteLine("Status=" + result.Status + ", Code=" + result.Code
    ///             + ", Function=" + result.Function + ", NativeCode=" + result.NativeCode
    ///             + ", PrintInvoked=" + result.PrintInvoked
    ///             + ", PrintCode=" + result.PrintCode + ", MovementCode=" + result.MovementCode
    ///             + ", CleanupCode=" + result.CleanupCode);
    ///         if (!result.IsSuccess) break; // 이미 일부 출력됐을 수 있으므로 재시도하지 않습니다.
    ///     }
    /// }
    /// // 관리 입력 예외와 Dispose의 해제 실패 예외는 앱의 상위 오류 처리에서 다룹니다.
    /// </code>
    /// </example>
    internal static class BT003CtrlWrapper
    {
        #region 프린터 및 RFID 연결

        /// <summary>연결에 사용할 프린터의 인터페이스와 포트를 지정합니다.</summary>
        /// <param name="ifType">인터페이스 종류입니다. 0: RS-232, 1: USB, 2: TCP/IP.</param>
        /// <param name="strPortName">인터페이스별 포트 이름 또는 번호입니다. 매뉴얼 예: "USB1", COM5의 "5", TCP 포트 "9100".</param>
        /// <param name="strIpAddr">TCP/IP 연결의 IP 주소입니다. USB와 RS-232는 빈 문자열을 지정합니다.</param>
        /// <returns>0: 정상, 1: 이미 연결된 경우. 연결 상태 조회나 장치 오류표의 1과는 의미가 다릅니다.</returns>
        /// <remarks>
        /// <para>문서 출처: NFC BT003-M01-04 API Programming Manual Rev.1.3 (2022-05-20), 1.API Reference, #1 「프린터 인터페이스 포트 지정」, PDF p.3.</para>
        /// <para>제조사 원문 프로토타입 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```cpp
        /// int SetPrinterPort (USHORT ifType, LPCTSTR strPortName, LPCTSTR strIpAddr);
        /// ```
        /// </code>
        /// <para>제조사 원문 반환값 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// `0 : 정상, 1 : 연결된 경우`
        /// </code>
        /// <para>제조사 원문 인수 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// | 인수 | 내용 |
        /// |---|---|
        /// | `ifType` | 인터페이스 종류 (0:RS-232, 1:USB, 2:TCP/IP) |
        /// | `strPortName` | 인터페이스별 포트이름 또는 번호 (COM5의 경우 5, TCPIP의 경우 9100 등) |
        /// | `strIpAddr` | TCPIP의 경우 IP 주소. USB와 RS232의 경우 빈문자열 |
        /// </code>
        /// <para>제조사 원문 설명 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// 응용프로그램에서 프린터에 연결하여 사용할 포트를 지정한다.
        /// </code>
        /// <para>제조사 원문 예제 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```text
        /// // USB : USB
        /// SetPrinterPort(1, “USB1”,””);
        /// // RS232 : COM5
        /// SetPrinterPort(0, “5”,””);
        /// // TCPIP
        /// SetPrinterPort(2,”9100”, “192.168.0.198”);
        /// ```
        /// </code>
        /// <para>감사 의견(원문과 구분): SetPrinterPort의 반환값 1은 이 함수에 한하여 이미 연결된 상태를 나타내며, 오류표 1(Paper out)과 다릅니다.</para>
        /// <para>추가 검증 및 사용 주의사항:</para>
        /// 실제 연결은 DeviceConnect로 수행합니다.
        /// 2026-10-13의 직접 USB 인쇄는 SetPrinterPort(1, "0", "")로 확인했습니다. COM3의 RFID 포트와 구분합니다.
        /// 숫자 "0"이 다른 PC·다른 프린터에서도 같은 장치를 가리킨다는 보장은 없습니다. 사용할 장치의 포트를 지정합니다.
        /// </remarks>
        /// <example>
        /// 제조사 포트 지정 예제입니다. 사용할 인터페이스 하나를 선택합니다.
        /// <code>
        /// int usbCode = BT003CtrlWrapper.SetPrinterPort(1, "USB1", "");
        /// // RS-232 또는 TCP/IP를 사용하는 경우의 대안입니다.
        /// // int serialCode = BT003CtrlWrapper.SetPrinterPort(0, "5", "");
        /// // int tcpCode = BT003CtrlWrapper.SetPrinterPort(2, "9100", "192.168.0.198");
        /// </code>
        /// </example>
        [DllImport("BlackfishNfcLib.dll", CallingConvention = CallingConvention.StdCall)]
