        /// <summary>연결에 사용할 RFID 모듈의 인터페이스와 포트를 지정합니다.</summary>
        /// <param name="ifType">인터페이스 종류입니다. 0: RS-232, 2: TCP/IP. RFID 모듈은 USB를 지원하지 않습니다.</param>
        /// <param name="strPortName">포트 번호 문자열입니다. COM6은 "6", TCP/IP는 TCP 포트 번호를 지정합니다.</param>
        /// <param name="strIpAddr">TCP/IP 연결의 IP 주소입니다. RS-232는 빈 문자열을 지정합니다.</param>
        /// <returns>0: 정상, -1: 지원되지 않는 인터페이스.</returns>
        /// <remarks>
