        /// <summary>BTPL 인쇄서식을 파일로 지정합니다.</summary>
        /// <param name="strFormFile">인쇄서식 파일의 절대경로입니다.</param>
        /// <returns>0: 등록 처리 정상. 현재 SDK에서 실제 파일 열기는 발행 시점이므로 읽기·인쇄 성공 보장이 아닙니다. 오류표는 클래스 주석을 참조합니다.</returns>
        /// <remarks>
        /// <para>문서 출처: NFC BT003-M01-04 API Programming Manual Rev.1.3 (2022-05-20), 1.API Reference, #5 「인쇄서식-서식파일 지정」, PDF p.4.</para>
        /// <para>제조사 원문 프로토타입 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```cpp
        /// intSetPrintFormFile(LPCTSTR strFileName);
        /// ```
        /// </code>
        /// <para>제조사 원문 반환값 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// `수행결과 (0:정상)`
        /// </code>
        /// <para>제조사 원문 인수 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// `strFileName : 서식파일명(절대경로명)`
        /// </code>
        /// <para>제조사 원문 설명 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// 태그발행에 필요한 인쇄서식을 파일로 지정한다. 인쇄서식을 지정하는 방법은 파일로 지정하는 방법과 문자열데이터로 지정하는 방법 중 하나를 반드시 이용하여야 한다.
        ///
        /// 인쇄서식은 라벨의 규격과, 인쇄서식, 인쇄농도 등 프린터를 제어하기 위한 명령들이 BT-003 프로그래밍언어(BTPL)에 의해 작성되어야 한다.
        ///
        /// 인쇄서식이 지정되지 않은 상태에서 태그발행을 시작하면 103번 오류코드가 반환된다.
        ///
        /// 인쇄서식 작성과 관련해서는 별도의 BTPL Programming Guide를 참조한다.
        /// </code>
        /// <para>제조사 원문 예제 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```text
        /// SetPrintFormFile(“C:\\Test\\myForm.txt”);
        /// ```
        /// </code>
        /// <para>감사 의견(원문과 구분): 인쇄서식을 지정하지 않은 채 태그발행을 시작하면 문서는 오류코드 103을 명시합니다. 실제 DLL/프린터에서 본 사례를 검증한 것은 아닙니다.</para>
        /// <para>추가 검증 및 사용 주의사항:</para>
        /// 파일 또는 문자열 방식으로 서식을 먼저 지정해야 합니다.
        /// 매뉴얼은 서식이 지정되지 않은 상태에서 태그발행을 시작하면 103 오류가 반환된다고 설명합니다.
        /// <para>제공 SDK의 파일 열기와 103</para>
        /// 확인한 x86/x64 SDK는 여기서 파일 경로를 저장하고, StartLabelPrint의 파일 처리 단계에서 파일을 다시 엽니다.
        /// 따라서 등록 0은 파일의 존재·읽기 성공·AW 처리·물리 인쇄 성공까지 확인한 결과가 아닙니다.
        /// 파일 재열기는 공유 없는 읽기(CreateFileA의 dwShareMode=0)를 사용하며, 열기 실패를 103으로 처리합니다.
        /// 파일이 실제 존재해도 같은 파일의 FileStream(FileAccess.Read, FileShare.Read)이 살아 있으면 공유 충돌이 생깁니다.
        /// 이 조건은 SDK 분기 분석과 Windows 파일 열기 재현으로 확인했습니다. SDK 내부 GetLastError를 실시간 계측한 결과는 아닙니다.
        /// 파일 핸들을 먼저 닫은 직접 등록 경로는 정상 인쇄됐습니다. 제품의 파일 잠금 유지 계약에는 그 방식을 적용하지 않습니다.
        /// 공개 제품 PrintFile은 CP949 내용을 읽어 SetPrintFormString으로 등록하므로 원본 파일 재열기를 피하면서 잠금을 정리까지 유지합니다.
        /// 103의 제조사 문구 "Form file not found"를 파일 부재만의 판정으로 사용하지 않습니다. 서식 미지정 사례와 공유 충돌 사례도 구별합니다.
        /// </remarks>
        /// <example>
        /// 제조사 서식 파일 지정 예제를 실행 폴더의 경로로 정리했습니다. 파일을 먼저 준비하고, 반환값을 확인한 후 인쇄를 요청합니다.
        /// <code>
        /// string formPath = System.IO.Path.Combine(
        ///     AppDomain.CurrentDomain.BaseDirectory, "myForm.txt");
        /// int code = BT003CtrlWrapper.SetPrintFormFile(formPath);
        /// </code>
        /// </example>
        [DllImport("BlackfishNfcLib.dll", CallingConvention = CallingConvention.StdCall)]
        public static extern int SetPrintFormFile(string strFormFile);

        /// <summary>BTPL 인쇄서식을 문자열로 지정합니다.</summary>
        /// <param name="strFormData">각 명령 끝에 CRLF(\r\n)가 포함된 BTPL 서식 문자열입니다.</param>
        /// <returns>0: 정상. 오류의 상세 내용은 이 클래스 주석의 공통 반환 코드표를 참조합니다.</returns>
        /// <remarks>
        /// <para>문서 출처: NFC BT003-M01-04 API Programming Manual Rev.1.3 (2022-05-20), 1.API Reference, #6 「인쇄서식-문자열서식 지정」, PDF p.4.</para>
        /// <para>제조사 원문 프로토타입 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```cpp
        /// intSetPrintFormString(LPCTSTR strForm);
        /// ```
        /// </code>
        /// <para>제조사 원문 반환값 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// `수행결과 (0 : 정상)`
        /// </code>
        /// <para>제조사 원문 인수 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// `strForm : 서식데이터`
        /// </code>
        /// <para>제조사 원문 설명 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// 별도의 서식파일을 사용하지 않고, 서식의 내용을 직접 문자열로 지정할 때 사용한다.
        ///
        /// 서식내용의 각 명령끝은 반드시 줄바꿈문자(“\r\n”)가 포함 되어야 한다.
        ///
        /// 서식파일 지정과 동시에 사용될 경우에는 서식파일 지정이 우선 적용 된다.
        /// </code>
        /// <para>제조사 원문 예제 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```text
        /// string str= “^Q50,5,0\r\n^W100\r\n”
        /// str+= “^L\r\n”;
        /// str+= “AZ,100,50,1,1,0,0,^V00\r\n”;
        /// str+= “E\r\n”;
        /// SetPrintFormString( str);
        /// ```
        /// </code>
        /// <para>사용 주의: 각 명령은 CRLF(\r\n)로 끝나야 합니다. 파일 우선이라는 설명은 위 제조사 원문이며, 이번 실기는 두 방식을 혼용하지 않았습니다.</para>
        /// <para>추가 검증 및 사용 주의사항:</para>
        /// ResetForm 뒤 이 함수로 서식을 등록하고, 변수 서식이면 SetPrintFormVariableData로 완전한 값을 지정한 후 StartLabelPrint를 호출합니다.
        /// 마지막 E도 CRLF로 끝냅니다. Wrapper는 줄끝이나 인코딩을 검사·정규화하지 않습니다.
        /// 이번 혼합 LF/CRLF 입력에서는 101과 일부 출력을 관측했고, CRLF로 정리한 서식과 제품이 정규화한 파일은 정상 출력됐습니다.
        /// 모든 101이 줄끝 때문이라는 뜻은 아닙니다. 현재 제품 Print/PrintFile은 CRLF 정규화를 수행합니다.
        /// AW 글꼴과 변수 치환은 SDK가 처리합니다. 파일 내용을 이 함수로 등록할 때 파일 경로를 문자열 서식 대신 넘기지 않습니다.
        /// </remarks>
        /// <example>
        /// 제조사 문자열 서식 예제를 C# 문자열로 정리했습니다. ^V00의 값은 별도로 지정합니다.
        /// <code>
        /// string form = "^Q50,5,0\r\n^W100\r\n"
        ///     + "^L\r\n"
        ///     + "AZ,100,50,1,1,0,0,^V00\r\n"
        ///     + "E\r\n";
        /// int code = BT003CtrlWrapper.SetPrintFormString(form);
        /// </code>
        /// </example>
        [DllImport("BlackfishNfcLib.dll", CallingConvention = CallingConvention.StdCall)]
        public static extern int SetPrintFormString(string strFormData);

        /// <summary>파일 또는 문자열로 지정한 인쇄서식을 초기화합니다.</summary>
        /// <remarks>
        /// <para>문서 출처: NFC BT003-M01-04 API Programming Manual Rev.1.3 (2022-05-20), 1.API Reference, #7 「인쇄서식-초기화」, PDF p.4.</para>
        /// <para>제조사 원문 프로토타입 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```cpp
        /// void ResetForm();
        /// ```
        /// </code>
        /// <para>제조사 원문 반환값 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// 없음
        /// </code>
        /// <para>제조사 원문 인수 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// 없음
        /// </code>
        /// <para>제조사 원문 설명 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// SetPrintFormFile 또는 SetPrintFormString 메소드에 의해 지정된 모든 인쇄서식을 초기화한다.
        ///
        /// 이 메소드를 호출한 뒤에 새로 인쇄하기 위해서는 반드시 인쇄서식을 새로 지정하여야 한다.
        ///
        /// 인쇄서식이 지정되지 않은 상태에서 태그발행을 시작하면 103번 오류코드가 반환된다.
        /// </code>
        /// <para>제조사 원문 예제 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```text
        /// ResetForm();
        /// ```
        /// </code>
        /// <para>감사 의견(원문과 구분): ResetForm 후 새 인쇄를 시작하려면 서식을 재지정해야 합니다. 가변 데이터와 RFID 데이터의 초기화 여부는 원문에 명시되어 있지 않습니다.</para>
        /// <para>추가 검증 및 사용 주의사항:</para>
        /// 다음 인쇄 전에 서식을 새로 지정해야 합니다.
        /// 가변데이터까지 초기화되는지는 매뉴얼에 명시되어 있지 않습니다.
        /// 다음 변수 서식에는 모든 값을 다시 등록합니다. 이 함수는 프린터의 용지 원점·배출 위치를 초기화하거나 이동시키지 않습니다.
        /// </remarks>
        /// <example>
        /// 제조사 초기화 예제입니다. 이후 인쇄하려면 파일 또는 문자열 서식을 새로 지정해야 합니다.
        /// <code>
        /// BT003CtrlWrapper.ResetForm();
        /// </code>
        /// </example>
        [DllImport("BlackfishNfcLib.dll", CallingConvention = CallingConvention.StdCall)]
        public static extern void ResetForm();

        /// <summary>인쇄서식의 가변변수에 대응할 문자열 데이터를 지정합니다.</summary>
        /// <param name="strVariableData">기본 항목 구분자 "!!"로 나눈 데이터입니다. 첫 항목은 ^V00, 다음 항목은 ^V01에 대응합니다.</param>
        /// <returns>0: 정상. 오류의 상세 내용은 이 클래스 주석의 공통 반환 코드표를 참조합니다.</returns>
        /// <remarks>
        /// <para>문서 출처: NFC BT003-M01-04 API Programming Manual Rev.1.3 (2022-05-20), 1.API Reference, #8 「인쇄서식 가변데이터 지정」, PDF p.5.</para>
        /// <para>제조사 원문 프로토타입 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```cpp
        /// int SetPrintFormVariableData(LPCTSTR strVariableData);
        /// ```
        /// </code>
        /// <para>제조사 원문 반환값 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// `수행결과 (0 : 정상)`
        /// </code>
        /// <para>제조사 원문 인수 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// `strVariableData : 문자열 가변데이터`
        /// </code>
        /// <para>제조사 원문 설명 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// 인쇄서식파일 또는 인쇄서식 문자열내의 가변변수에 매핑될 데이터를 지정한다.
        ///
        /// 각 데이터의 구분은 항목구분자(기본값: “!!”)에 의해 구분되어야 한다.
        /// </code>
        /// <para>제조사 원문 예제 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// `&lt;mytest.txt 내용예시&gt;`
        ///
        /// ```text
        /// ^L
        /// AW,100,100,10,1,0,0, ^V00
        /// AW,100,200,12,1,0,0, ^V02
        /// AW,100,300,12,1,0,0, ^V01
        /// E
        /// ```
        ///
        /// `&lt;서식파일 및 가변 데이터지정&gt;`
        ///
        /// ```text
        /// SetPrintFormFile(“mytest.txt”);
        /// SetPrintFormVariableData( “홍길동!!1122334455!!20120201!!Blackfish BT-003”);
        /// ```
        ///
        /// `&lt;발행기로 전달되는 데이터&gt;`
        ///
        /// ```text
        /// ^L
        /// AW,100,100,10,1,0,0, 홍길동
        /// AW,100,200,12,1,0,0, 20120201
        /// AW,100,300,12,1,0,0, 1122334455
        /// E
        /// ```
        ///
        /// 위에서와 같이 서식에 ^V00, ^V01, ^V02 등과 같이 가변변수가 포함되어 있을때 SetPrintFormVariableData 메소드를 사용하여 각각의 가변변수에 대응될 데이터의 지정이 가능하다.
        ///
        /// 데이터를 “홍길동!!1122334455!!20120201!!Blackfish BT-003”로 지정할 경우 항목구분자 “!!”로 구분되는 데이터는 총4개가있으나, 서식에 포함된 가변변수는 ^V02가 마지막이기 때문에 마지막 데이터 “Blackfish BT-003”은 자동으로 생략된다.
        ///
        /// 데이터 매핑은 가변변수의 숫자에따라 순서대로 자동 매핑된다. 다음과 같은 인쇄서식을 사용하고 동일한 가변데이터를 지정하였을 경우 ^V03에는 “Blackfish BT-003” 데이터가 매핑된다.
        ///
        /// `&lt;mytest2.txt 내용예시&gt;`
        ///
        /// ```text
        /// ^L
        /// AW,100,100,10,1,0,0, ^V03
        /// E
        /// ```
        ///
        /// `&lt;서식파일 및 가변데이터 지정&gt;`
        ///
        /// ```text
        /// SetPrintFormFile(“mytest2.txt”);
        /// SetPrintFormVariableData(“홍길동!!1122334455!!20120201!!Blackfish BT-003”);
        /// ```
        /// </code>
        /// <para>감사 의견(원문과 구분): 원문은 ^V00, ^V01, ^V02에 순서대로 매핑하며 사용하지 않은 제4값은 생략한다고 명시합니다. ^V03이 등장하면 제4값을 사용합니다.</para>
        /// <para>추가 검증 및 사용 주의사항:</para>
        /// 변수 번호를 기준으로 매핑하며, 서식에서 사용하지 않는 추가 데이터는 생략됩니다.
        /// 부족한 데이터나 이전 호출 데이터의 유지·초기화 동작은 매뉴얼에 상세 정의가 없습니다.
        /// 이번 제품 계약은 V00부터 최고 참조 번호까지 누락 없이 매번 모든 값을 제공하는 것입니다. 변수 없는 서식에서만 등록을 생략합니다.
        /// 공개 Print/PrintFile에는 구분자로 합친 한 문자열 대신 각 값을 별도 인수로 전달합니다. 제품이 !!로 연결합니다.
        /// 제품은 빈 값·제어문자·!!·양 끝 !·NUL·CP949 왕복 불가 값을 거부합니다. Wrapper를 직접 호출하면 호출자가 검사해야 합니다.
        /// 실제 x86 1장과 x64 5회 교차 호출에서 ASCII·한글 두 변수와 매 요청 번호 변경을 확인했습니다.
        /// 일부 변수만 갱신하거나 값을 누락하는 경우와 ResetForm의 저장소 초기화는 실기로 보장하지 않습니다.
        /// </remarks>
        /// <example>
        /// 제조사 변수 매핑 예제를 합성 데이터로 정리했습니다. ^V00은 TEST, ^V01은 1122334455, ^V02는 20120201, ^V03은 Blackfish BT-003에 대응합니다.
        /// <code>
        /// int code = BT003CtrlWrapper.SetPrintFormVariableData(
        ///     "TEST!!1122334455!!20120201!!Blackfish BT-003");
        /// </code>
        /// <para>추가 C# 예제 — 제조사 원본의 별도 시나리오를 검증 가능한 호출 형식으로 정리:</para>
        /// <code>
        /// // 원문의 mytest.txt를 문자열 서식으로 구성한 대응 예제입니다. ^V00, ^V02, ^V01 순서입니다.
        /// string firstForm = "^L\r\n"
        ///     + "AW,100,100,10,1,0,0, ^V00\r\n"
        ///     + "AW,100,200,12,1,0,0, ^V02\r\n"
        ///     + "AW,100,300,12,1,0,0, ^V01\r\nE\r\n";
        /// int formCode = BT003CtrlWrapper.SetPrintFormString(firstForm);
        /// int variableCode = BT003CtrlWrapper.SetPrintFormVariableData(
        ///     "홍길동!!1122334455!!20120201!!Blackfish BT-003");
        /// // 출력 치환값: 홍길동, 20120201, 1122334455; 제4값은 사용하지 않습니다.
        /// // 다른 서식 예: "^L\r\nAW,100,100,10,1,0,0, ^V03\r\nE\r\n"
        /// // 위 서식에서는 ^V03에 Blackfish BT-003이 매핑됩니다.
        /// </code>
        /// </example>
        [DllImport("BlackfishNfcLib.dll", CallingConvention = CallingConvention.StdCall)]
        public static extern int SetPrintFormVariableData(string strVariableData);

        /// <summary>인쇄 속도와 농도를 지정합니다.</summary>
        /// <param name="iSpeed">인쇄 속도입니다. 단위: ips. 지원 범위는 프린터 종류에 따라 다릅니다.</param>
        /// <param name="iDarkness">인쇄 농도입니다. 범위: 1~19. 값이 클수록 진합니다.</param>
        /// <returns>0: 정상, 그 외: 이 클래스 주석의 공통 반환 코드표를 참조합니다.</returns>
        /// <remarks>
        /// <para>문서 출처: NFC BT003-M01-04 API Programming Manual Rev.1.3 (2022-05-20), 1.API Reference, #11 「인쇄옵션 설정 (인쇄속도, 인쇄농도)」, PDF p.6.</para>
        /// <para>제조사 원문 프로토타입 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```cpp
        /// int SetPrintingOption(USHORT iSpeed, USHORT iDarkness);
        /// ```
        /// </code>
        /// <para>제조사 원문 반환값 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// `실행결과 (0:성공, 그외의 경우 오류코드 참조)`
        /// </code>
        /// <para>제조사 원문 인수 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// | 인수 | 내용 |
        /// |---|---|
        /// | `iSpeed` | 인쇄속도 (단위 ips, 값의범위는 프린터 종류에 따라 다름) |
        /// | `iDarkness` | 인쇄농도 (1 ~ 19), 값이 클수록 진함 |
        /// </code>
        /// <para>제조사 원문 설명 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// 프린터의 인쇄속도와 인쇄농도를 지정한다.
        ///
        /// 인쇄속도는 ^S명령에 대응되고, 인쇄농도는 ^H명령에 대응된다.
        ///
        /// 라벨설정과 마찬가지로 인쇄서식에 관련명령이 없을경우에 적용된다.
        ///
        /// 인쇄서식에 ^S명령이나, ^H 명령이 있을경우에는 이메소드에서 지정한 해당 설정값은 무시된다.
        /// </code>
        /// <para>제조사 원문 예제 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```text
        /// // 인쇄속도4ips, 농도12지정
        /// SetPrintingOption(4, 12);
        /// ```
        /// </code>
        /// <para>감사 의견(원문과 구분): 서식의 ^S/^H 명령이 이 함수로 설정한 속도와 농도보다 우선합니다.</para>
        /// <para>추가 검증 및 사용 주의사항:</para>
        /// 서식에 ^S 또는 ^H 명령이 있으면 해당 서식 설정이 우선합니다.
        /// 공개 제품 SetPrintingOptions(5, 19)는 실제 x64 연결에서 0을 확인했습니다. 이번 인쇄 서식에도 ^S5/^H19가 있습니다.
        /// 이 설정 호출 결과가 모든 속도·농도의 실제 인쇄 품질이나 다른 모델의 지원 범위를 검증한 것은 아닙니다.
        /// </remarks>
        /// <example>
        /// 제조사 예제입니다. 인쇄 속도 4 ips와 농도 12를 지정합니다.
        /// <code>
        /// int code = BT003CtrlWrapper.SetPrintingOption(4, 12);
        /// </code>
        /// </example>
        [DllImport("BlackfishNfcLib.dll", CallingConvention = CallingConvention.StdCall)]
        public static extern int SetPrintingOption(ushort iSpeed, ushort iDarkness);

        /// <summary>라벨의 규격과 용지 인식 방법을 지정합니다.</summary>
        /// <param name="iLabelWidth">라벨 너비입니다. 단위: mm.</param>
        /// <param name="iLabelHeight">라벨 높이 또는 길이입니다. 단위: mm.</param>
        /// <param name="iGap">라벨 간격입니다. 단위: mm.</param>
        /// <param name="iType">용지 인식 방법입니다. 0: Black-Mark, 1: Gap, 2: 연속용지.</param>
        /// <returns>0: 정상, 그 외: 이 클래스 주석의 공통 반환 코드표를 참조합니다.</returns>
        /// <remarks>
        /// <para>문서 출처: NFC BT003-M01-04 API Programming Manual Rev.1.3 (2022-05-20), 1.API Reference, #12 「라벨설정」, PDF p.7.</para>
        /// <para>제조사 원문 프로토타입 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```cpp
        /// int SetLabelSetting (USHORT iWidth, USHORT iHeight, USHORT iGap, USHORT iType);
        /// ```
        /// </code>
        /// <para>제조사 원문 반환값 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// `메소드의 실행결과 ( 0 : 성공, 그외의 경우에는 오류코드 참조 )`
        /// </code>
        /// <para>제조사 원문 인수 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// | 인수 | 내용 |
        /// |---|---|
        /// | `iWidth` | 라벨의 너비 (mm) |
        /// | `iHeight` | 라벨의 높이, 길이 (mm) |
        /// | `iGap` | 라벨의 간격 (mm) |
        /// | `iType` | 라벨의 인식 방법 (0:Black-Mark, 1:Gap, 2:연속용지) |
        /// </code>
        /// <para>제조사 원문 설명 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// 라벨의 규격을 설정한다. 라벨의 규격은 길이, 너비, 간격을 mm 단위로 입력한다.
        ///
        /// 라벨인식방법은 프린터가 라벨을 인식하는 방법을 지정하는 것으로 Black-mark, Gap, 연속용지 중 사용할 라벨에 맞추어 지정한다.
        ///
        /// 인쇄서식내에 라벨규격 관련 명령 (^Q, ^W 등)이 있을 경우에는 서식내용이 적용되고, 이 메서드에 의해 지정된 내용은 무시된다. 다만, 레지스트리에 저장되게 되어 인쇄서식에 ^Q, ^W 명령이 없을 경우에 대체되어 사용된다.
        /// </code>
        /// <para>제조사 원문 예제 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```text
        /// // 너비 : 100mm, 길이 : 50mm, 간격 : 5mm, Black-mark media일 경우
        /// SetLabelSetting (100, 50, 5, 0);
        /// ```
        /// </code>
        /// <para>감사 의견(원문과 구분): 설정 값은 레지스트리에 저장되며, 서식의 ^Q/^W가 해당 설정에 우선합니다.</para>
        /// <para>추가 검증 및 사용 주의사항:</para>
        /// 설정은 Registry에 저장됩니다.
        /// 서식에 관련 명령(^Q, ^W 등)이 있으면 서식이 우선하며, 없을 때 이 설정을 대체값으로 사용합니다.
        /// </remarks>
        /// <example>
        /// 제조사 예제입니다. 너비 100 mm, 길이 50 mm, 간격 5 mm, Black-Mark 용지를 지정합니다.
        /// <code>
        /// int code = BT003CtrlWrapper.SetLabelSetting(100, 50, 5, 0);
        /// </code>
        /// </example>
        [DllImport("BlackfishNfcLib.dll", CallingConvention = CallingConvention.StdCall)]
        public static extern int SetLabelSetting(ushort iLabelWidth, ushort iLabelHeight, ushort iGap, ushort iType);

        /// <summary>프린터 응답을 모니터링하기 위한 SDK 수신 버퍼의 사용 여부를 지정합니다.</summary>
        /// <param name="iUseBuffer">1: 수신 버퍼 사용, 0: 미사용.</param>
        /// <returns>0: 정상, 그 외: 이 클래스 주석의 공통 반환 코드표를 참조합니다.</returns>
        /// <remarks>
        /// <para>문서 출처: NFC BT003-M01-04 API Programming Manual Rev.1.3 (2022-05-20), 1.API Reference, #13 「프린터 응답메시지 수신버퍼 사용여부」, PDF p.7.</para>
        /// <para>제조사 원문 프로토타입 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```cpp
        /// int SetUseResponseBuffer(USHORT iUseBuffer);
        /// ```
        /// </code>
        /// <para>제조사 원문 반환값 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// `메소드의 실행결과 ( 0 : 성공, 그외의 경우에는 오류코드 참조 )`
        /// </code>
        /// <para>제조사 원문 인수 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// `iUseBuffer : 수신버퍼 사용여부 (1:사용, 0:미사용)`
        /// </code>
        /// <para>제조사 원문 설명 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// 프린터로부터 수신된 데이터를 Application이 모니터링하는데 필요한 컴포넌트 수신버퍼의 활성화 여부를 결정한다.
        ///
        /// 수신버퍼 사용이 활성화 된 경우 Application에서는 ReadResponseMessage 메서드를 주기적으로 호출함으로써 수신버퍼의 내용을 읽어 들일 수 있다.
        /// </code>
        /// <para>제조사 원문 예제 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```text
        /// SetUseResponseBuffer(1);
        /// ```
        /// </code>
        /// <para>감사 의견(원문과 구분): 매뉴얼 #14 ReadResponseMessage는 이번 제공 DLL의 x86/x64 export 양쪽 모두에 없습니다. SetUseResponseBuffer가 이 기능의 실사용을 보장하지 않습니다.</para>
        /// <para>추가 검증 및 사용 주의사항:</para>
        /// 매뉴얼의 수신 데이터 읽기 함수 ReadResponseMessage는 이 Wrapper에 선언되어 있지 않습니다.
        /// 수신 버퍼 활성화만으로 응답 내용을 읽거나 장치 상태를 확인한 것은 아닙니다.
        /// </remarks>
        /// <example>
        /// 제조사 수신 버퍼 활성화 예제입니다. 읽기 함수가 선언되어 있지 않으므로 이 호출만으로 수신 데이터를 읽을 수는 없습니다.
        /// <code>
        /// int code = BT003CtrlWrapper.SetUseResponseBuffer(1);
        /// </code>
        /// </example>
        [DllImport("BlackfishNfcLib.dll", CallingConvention = CallingConvention.StdCall)]
        public static extern int SetUseResponseBuffer(ushort iUseBuffer);

        // 매뉴얼 #14: ReadResponseMessage는 현재 제공된 x86/x64 DLL에 export되지 않습니다.
        // P/Invoke로 추가하면 EntryPointNotFoundException이 발생할 수 있습니다.
        // 함수의 원문 원형·설명·예제는 클래스 주석 및 API 추적 문서에 보존했습니다.

        #endregion
        #region RFID 발행 조건 및 레코드

        /// <summary>태그 종류·잠금·재시도·보안 등 RFID 태그발행 조건을 지정합니다.</summary>
        /// <param name="iCardType">태그 칩 코드입니다. 이 클래스 주석의 태그 칩 코드표에서 값을 확인할 수 있습니다.</param>
        /// <param name="iLockMode">0: 잠금 없음, 1: Soft-lock, 2: Physical-lock, 3: 두 방식 모두. Physical-lock은 복구할 수 없습니다.</param>
        /// <param name="iVerify">발행 후 검증 옵션입니다. 매뉴얼 인수표는 0으로 고정하도록 명시합니다.</param>
        /// <param name="iRetry">오류 시 시도 횟수 설정입니다. 매뉴얼 예: 2는 최초 시도 후 1회 재시도, 3은 2회 재시도.</param>
        /// <param name="iOperationSafeMode">안전 모드입니다. 현재 미지원이므로 매뉴얼 인수표에 따라 0을 지정합니다.</param>
        /// <param name="iProtection">칩 보안 기능 사용 여부입니다. 0: 미사용, 1: 사용.</param>
        /// <returns>0: 정상, 그 외: 이 클래스 주석의 공통 반환 코드표를 참조합니다.</returns>
        /// <remarks>
        /// <para>문서 출처: NFC BT003-M01-04 API Programming Manual Rev.1.3 (2022-05-20), 1.API Reference, #15 「태그발행 조건 지정」, PDF p.8.</para>
        /// <para>제조사 원문 프로토타입 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```cpp
        /// int SetRfidCondition (USHORT iCardType, USHORT iLockMode, USHORT iVerify, USHORT iRetry,
        /// USHORT iSafeMode, USHORT iProtection);
        /// ```
        /// </code>
        /// <para>제조사 원문 반환값 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// `메소드의 실행결과 ( 0 : 성공, 그외의 경우에는 오류코드 참조 )`
        /// </code>
        /// <para>제조사 원문 인수 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// | 인수 | 내용 |
        /// |---|---|
        /// | `iCardType` | 태그 Chip 종류. 매뉴얼 뒤편 Chip 코드표 참조 |
        /// | `iLockMode` | Lock 방법. (0:None, 1: Soft-lock, 2:Physical-lock, 3:Soft-lock + Physical-lock) |
        /// | `iVerify` | 태그발행 후 다시 읽어 검증할지 여부 (0:None, 1:검증). 0으로 고정. |
        /// | `iRetry` | 태그발행 중 오류가 발생하였을 경우 재시도 횟수. 값이 2일 경우 추가적으로 1번 재시도하고 , 3일 경우 2번까지 재시도함 |
        /// | `iSafeMode` | 현재 미지원으로 0으로 고정. |
        /// | `iProtection` | Chip에서 제공하는 보안기능 사용 여부. 0:사용안함, 1:사용함 |
        /// </code>
        /// <para>제조사 원문 설명 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// 태그발행을 시작하기 전에 반드시 선행되어야 하는 메서드이다.
        ///
        /// 만일 위 메서드로 조건을 지정하지 않을 경우, 기본값에 의해 태그발행 프로세스가 진행된다. 이는, 사용자가 원치 않는 결과를 초래할 수 있기 때문에, 적어도 프로그램을 재기동하여 처음 태그발행을 시작하기 전에 한번은 사용자가 원하는 값으로 위 메서드를 실행할 것을 권장한다.
        ///
        /// ### Lock
        ///
        /// - 0 : 어떠한 lock 동작도 수행하지 않는다.
        /// - 1 : Soft-lock. CC 블록에 특정비트를 체크함으로써 NFC Compatible Device에서 Read-Only State로 인식하게 한다. 이 상태는 Physical-lock을 수행하지 않음으로써 특정블럭을 지정하고 데이터를 기록할 경우에는 데이터 기록이 가능하다. 다만, 스마트폰과 같은 NFC Device에서 일반적인 앱으로 데이터를 기록할 경우에는 기록이 되지 않는다.
        /// - 2 : Physical-lock. 태그 메모리 전체를 칩에서 제공하는 Lock 기능을 사용하여 물리적으로 Read-Only 상태로 만든다. 물리적으로 잠금이 된 태그는 Lock 이전상태로 복원될 수 없다.
        /// - 3 : 1과 2의 결합. NDEF Message를 사용할 경우에 안전하게 Lock을 하고 싶다면 이 옵션을 선택.
        ///
        /// ### Verify
        ///
        /// - 기본적으로 태그발행 과정 중 다양한 프로세스를 거치며 오류가 있을 경우 태그에 별도의 지정된 표시를 하게 됨으로써 추가적인 검증을 거치지 않아도 되나, 반드시 확인할 필요가 있을 경우에 사용
        /// - 단, 검증을 위해 추가적인 RFID Operation을 수행하게 됨으로써 추가적인 소요시간 발생이 되므로 반드시 필요한 경우에만 지정할 것을 추천한다.
        ///
        /// ### Retry
        ///
        /// - 발행 중 오류가 있을 경우에는 지정된 Retry 횟수만큼 반복하게 된다. 예를 들어 retry값이 2로 지정된 경우 처음 오류태그를 포함하여 2번 반복실행 하게 된다.
        ///
        /// ### SafeMode
        ///
        /// - 기본적으로 태그발행과정에서 태그에 대한 다양한 체크 과정을 통해 발행이 되지만 발행속도를 고려하지 않을 수 없다. SafeMode를 사용할 경우에는 좀더 다양한 체크과정을 통해 보다 안전하게 태그발행이 가능하다. 현재 컴포넌트에서는 지원하지 않으며, 다음 버전에서 제공된다.
        ///
        /// ### Protection
        ///
        /// - Chip에서 제공하는 Seruciry 기능을 사용할 지 여부를 결정한다.
        /// - 1일 경우 태그발행시 지정된 password 및 protection 옵션 정보를 사용하여 protection을 수행한다.
        /// </code>
        /// <para>제조사 원문 예제 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```text
        /// // ICODE SLIX-S, Soft lock &amp; Physical lock, none verify, retry 2회, 안전모드 미사용,
        /// // protection 미사용
        /// SetRfidCondition (55, 3, 0, 2, 1, 0);
        /// ```
        /// </code>
        /// <para>감사 의견(원문과 구분): 매뉴얼 인수표는 iVerify=0, iSafeMode=0 고정으로 설명하지만 상세 설명에는 검증 기능 언급이 있고, 예제는 iSafeMode=1입니다. 정정 C# 예제는 미지원 기능을 켜지 않도록 0을 사용합니다. 물리적 잠금은 복구할 수 없습니다.</para>
        /// <para>추가 검증 및 사용 주의사항:</para>
        /// 원하지 않는 기본 조건을 피하도록 태그발행 전에 지정합니다.
        /// 검증 옵션의 추가 설명과 안전 모드의 예제는 인수표와 일치하지 않아, 위 주석은 인수표를 기준으로 합니다.
        /// </remarks>
        /// <example>
        /// 제조사 ICODE SLIX-S 예제입니다. 미지원 안전 모드 값은 인수표에 맞춰 0으로 정리했습니다. 잠금 값 3은 복구할 수 없는 Physical-lock을 포함합니다.
        /// <code>
        /// int code = BT003CtrlWrapper.SetRfidCondition(55, 3, 0, 2, 0, 0);
        /// </code>
        /// </example>
        [DllImport("BlackfishNfcLib.dll", CallingConvention = CallingConvention.StdCall)]
        public static extern int SetRfidCondition(ushort iCardType, ushort iLockMode, ushort iVerify, ushort iRetry, ushort iOperationSafeMode, ushort iProtection);

        /// <summary>태그에 기록할 데이터 유형을 지정합니다.</summary>
        /// <param name="iType">1: NDEF 메시지만, 2: NDEF 메시지와 블록 데이터, 3: 블록 데이터만.</param>
        /// <returns>0: 정상, 그 외: 이 클래스 주석의 공통 반환 코드표를 참조합니다.</returns>
        /// <remarks>
        /// <para>문서 출처: NFC BT003-M01-04 API Programming Manual Rev.1.3 (2022-05-20), 1.API Reference, #16 「기록할 RFID 데이터 유형 지정」, PDF p.9.</para>
        /// <para>제조사 원문 프로토타입 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```cpp
        /// int SetWritingDataType (USHORT iType);
        /// ```
        /// </code>
        /// <para>제조사 원문 반환값 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// `수행결과 (0:성공, 그외의 경우 오류코드 참조)`
        /// </code>
        /// <para>제조사 원문 인수 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// `iType : 데이터 유형 (1:NDEF Message Only, 2:NDEF Message와 Block Data, 3:Block Data Only)`
        /// </code>
        /// <para>제조사 원문 설명 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// 태그에 기록할 데이터의 유형을 지정한다.
        ///
        /// 예를 들어, URI 레코드나 TEXT 레코드, SmartPoster 레코드 등 NDEF 메시지를 기록할 경우에는 1, 특정블럭 또는 페이지에 지정하는 데이터를 기록하고자 할 경우에는 3, 위 두가지 데이터를 혼용할 경우에는 2를 지정한다.
        ///
        /// 위 유형에 따라 별도로 데이터 지정 메서드를 호출하여 데이터를 지정하여야 한다.
        /// </code>
        /// <para>제조사 원문 예제 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```text
        /// // NDEF Message만을 기록할 경우
        /// ClearNfcRecord();
        /// SetWritingDataType(1);
        /// AddNfcUriRecord(“http://www.bitekps.com”);
        ///
        /// // NDEF Message와 Block Data를 함께 기록할 경우
        /// ClearNfcRecord();
        /// SetWritingDataType(2);
        /// AddNfcUriRecord(“http://www.bitekps.com”);
        /// SetTagBlockData(10,”0A10EF23”);
        /// ```
        /// </code>
        /// <para>감사 의견(원문과 구분): 원문은 iType=1, 2, 3을 정의합니다. #17 설명에서는 NDEF-only를 0으로 오기하므로 인수표의 1을 기준으로 합니다.</para>
        /// <para>추가 검증 및 사용 주의사항:</para>
        /// 선택한 유형에 맞는 데이터 지정 API를 별도로 호출해야 합니다.
        /// </remarks>
        /// <example>
        /// 제조사 NDEF 전용 설정 예제를 정리했습니다. 각 단계의 반환값을 확인한 뒤 다음 단계를 진행합니다.
        /// <code>
        /// int clearCode = BT003CtrlWrapper.ClearNfcRecord();
        /// int typeCode = BT003CtrlWrapper.SetWritingDataType(1);
        /// int uriCode = BT003CtrlWrapper.AddNfcUriRecord("http://www.bitekps.com");
        /// </code>
        /// <para>추가 C# 예제 — 제조사 원본의 별도 시나리오를 검증 가능한 호출 형식으로 정리:</para>
        /// <code>
        /// // 제조사 문서의 NDEF + Block 혼합 사용례입니다. 발행은 수행하지 않습니다.
        /// int ndefClear = BT003CtrlWrapper.ClearNfcRecord();
        /// int blockClear = BT003CtrlWrapper.ClearBlockData();
        /// // 각 단계가 정상인지 확인한 뒤 다음 API를 호출합니다.
        /// int typeCode = BT003CtrlWrapper.SetWritingDataType(2);
        /// int uriCode = BT003CtrlWrapper.AddNfcUriRecord("http://www.bitekps.com");
        /// int blockCode = BT003CtrlWrapper.SetTagBlockData(10, "0A10EF23");
        /// </code>
        /// </example>
        [DllImport("BlackfishNfcLib.dll", CallingConvention = CallingConvention.StdCall)]
        public static extern int SetWritingDataType(ushort iType);

        /// <summary>NDEF 메시지에 URI 레코드 하나를 추가합니다.</summary>
        /// <param name="strUri">레코드에 포함할 URI 문자열입니다.</param>
        /// <returns>0: 정상, 그 외: 이 클래스 주석의 공통 반환 코드표를 참조합니다.</returns>
        /// <remarks>
        /// <para>문서 출처: NFC BT003-M01-04 API Programming Manual Rev.1.3 (2022-05-20), 1.API Reference, #17 「NDEF Message Record 추가 (URI Record)」, PDF p.10.</para>
        /// <para>제조사 원문 프로토타입 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```cpp
        /// int AddNfcUriRecord (LPCTSTR strUri);
        /// ```
        /// </code>
        /// <para>제조사 원문 반환값 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// `메소드의 실행결과 ( 0 : 성공, 그외의 경우에는 오류코드 참조 )`
        /// </code>
        /// <para>제조사 원문 인수 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// `strUri : URI 문자열. Ex) “http://www.bitekps.com”`
        /// </code>
        /// <para>제조사 원문 설명 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// WritingDataType 메소드를 통하여 데이터 유형을 0(Ndef Message Only) 또는 2(복합)를 선택한 경우에 이메서드에 의해 지정된 데이터를 활용하여 NDEF Message를 구성한다.
        ///
        /// NDEF Message는 다수의 레코드를 포함할 수 있으며, URI 타입 레코드 뿐만 아니라, NFC Forum에서 정의하는 모든 레코드에 대한 수용이 가능하다.
        ///
        /// 이 메서드는 NDEF Message 에 새로운 URI 레코드 하나를 추가해 준다.
        /// </code>
        /// <para>제조사 원문 예제 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```text
        /// // URI Record 두개를 추가할 경우
        /// AddNfcUriRecord(“http://www.bitekps.com”);
        /// AddNfcUriRecord(“http://www.anytron.net”);
        ///
        /// // URI Record와 Android Application Record를 추가할 경우
        /// AddNfcUriRecord(“http://www.bitekps.com”);
        /// AddNfcAARecord(“com.google.android.gm”); // gmail application
        /// ```
        /// </code>
        /// <para>감사 의견(원문과 구분): 원문의 NDEF-only 유형 0 표기는 #16 인수표 및 해당 예제의 1과 다릅니다.</para>
        /// <para>추가 검증 및 사용 주의사항:</para>
        /// 여러 번 호출하여 레코드를 추가할 수 있습니다.
        /// 매뉴얼 URI 설명의 NDEF 전용 유형 0은 데이터 유형 인수표의 1과 불일치합니다. 이 주석은 SetWritingDataType의 인수표를 기준으로 합니다.
        /// </remarks>
        /// <example>
        /// 제조사 URI 레코드 추가 예제입니다. NDEF를 사용할 데이터 유형을 먼저 지정해야 합니다.
        /// <code>
        /// int firstCode = BT003CtrlWrapper.AddNfcUriRecord("http://www.bitekps.com");
        /// int secondCode = BT003CtrlWrapper.AddNfcUriRecord("http://www.anytron.net");
        /// </code>
        /// <para>추가 C# 예제 — 제조사 원본의 별도 시나리오를 검증 가능한 호출 형식으로 정리:</para>
        /// <code>
        /// // 제조사 문서의 URI + Android Application Record 혼합 예제입니다.
        /// int clearCode = BT003CtrlWrapper.ClearNfcRecord();
        /// int typeCode = BT003CtrlWrapper.SetWritingDataType(1);
        /// int uriCode = BT003CtrlWrapper.AddNfcUriRecord("http://www.bitekps.com");
        /// int aarCode = BT003CtrlWrapper.AddNfcAARecord("com.google.android.gm");
        /// </code>
        /// </example>
        [DllImport("BlackfishNfcLib.dll", CallingConvention = CallingConvention.StdCall)]
        public static extern int AddNfcUriRecord(string strUri);

        /// <summary>NDEF 메시지에 텍스트 레코드 하나를 추가합니다.</summary>
        /// <param name="strText">레코드에 포함할 텍스트 데이터입니다.</param>
        /// <param name="strLocale">텍스트의 로케일 문자열입니다. 예: "ko", "en".</param>
        /// <returns>0: 정상, 그 외: 이 클래스 주석의 공통 반환 코드표를 참조합니다.</returns>
        /// <remarks>
        /// <para>문서 출처: NFC BT003-M01-04 API Programming Manual Rev.1.3 (2022-05-20), 1.API Reference, #18 「NDEF Message Record 추가 (Text Record)」, PDF p.10.</para>
        /// <para>제조사 원문 프로토타입 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```cpp
        /// Int AddNfcTextRecord (LPCTSTR strText, LPCTSTR strLocale);
        /// ```
        /// </code>
        /// <para>제조사 원문 반환값 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// `메소드의 실행결과 ( 0 : 성공, 그외의 경우에는 오류코드 참조 )`
        /// </code>
        /// <para>제조사 원문 인수 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// | 인수 | 내용 |
        /// |---|---|
        /// | `strText` | 텍스트 데이터. Ex) “This is a 테스트” |
        /// | `strLocale` | 로케일 문자열. Ex) “ko”, “en” ... |
        /// </code>
        /// <para>제조사 원문 설명 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// NDEF Message 에 새로운 TEXT 레코드 하나를 추가해 준다.
        ///
        /// TEXT Record에 대한 세부적인 사항은 NFC Forum의 “NFC Text Record Type Definition Technical Specification” 문서를 참조한다.
        /// </code>
        /// <para>제조사 원문 예제 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```text
        /// // TEXT Record 한개를 추가할 경우
        /// AddNfcTextRecord(“This is a test”, “ko”);
        ///
        /// // URI Record와 TEXT Record를 추가할 경우
        /// AddNfcUriRecord(“http://www.bitekps.com”);
        /// AddNfcTextRecord(“This is a test”, “ko”);
        /// ```
        /// </code>
        /// </remarks>
        /// <example>
        /// 제조사 텍스트 레코드 추가 예제입니다.
        /// <code>
        /// int code = BT003CtrlWrapper.AddNfcTextRecord("This is a test", "ko");
        /// </code>
        /// <para>추가 C# 예제 — 제조사 원본의 별도 시나리오를 검증 가능한 호출 형식으로 정리:</para>
        /// <code>
        /// // 제조사 문서의 URI + TEXT 혼합 예제입니다.
        /// int clearCode = BT003CtrlWrapper.ClearNfcRecord();
        /// int typeCode = BT003CtrlWrapper.SetWritingDataType(1);
        /// int uriCode = BT003CtrlWrapper.AddNfcUriRecord("http://www.bitekps.com");
        /// int textCode = BT003CtrlWrapper.AddNfcTextRecord("This is a test", "ko");
        /// </code>
        /// </example>
        [DllImport("BlackfishNfcLib.dll", CallingConvention = CallingConvention.StdCall)]
        public static extern int AddNfcTextRecord(string strText, string strLocale);

        /// <summary>NDEF 메시지에 URI와 텍스트를 포함한 Smart Poster 레코드 하나를 추가합니다.</summary>
