        /// <summary>NDEF 메시지에 External Type 레코드 하나를 추가합니다.</summary>
        /// <param name="strTypeName">레코드 타입 이름입니다. 예: "android.com:pkg".</param>
        /// <param name="strBinPayload">Payload 바이트를 나타내는 16진수 문자열입니다. 예: "01234"의 바이트 표현은 "3031323334".</param>
        /// <returns>0: 정상, 그 외: 이 클래스 주석의 공통 반환 코드표를 참조합니다.</returns>
        /// <remarks>
        /// <para>문서 출처: NFC BT003-M01-04 API Programming Manual Rev.1.3 (2022-05-20), 1.API Reference, #20 「NDEF Message Record 추가 (Well Known External Type Record)」, PDF p.11.</para>
        /// <para>제조사 원문 프로토타입 (원문 철자·오타·표기 보존):</para>
        /// <code>
        /// ```cpp
        /// int AddNfcExterRecord (LPCTSTR strTypeName, LPCTSTR strBinPayload);
