        /// // 선언부
        /// [DllImport("BT003Lib.dll", CallingConvention= CallingConvention.stdCall)]
        /// Public static extern int StartPrintingWithRfid([MarshalAs(UnmanagedType.LPWStr, SizeConst=
        /// 128)] StringBuilder retStr);
        /// // 메서드호출
        /// Private void btnStart_Click(object sender, EventArgs e)
        /// {
        ///     StringBuildersb= new StringBuilder(128);
        ///     StartPrintingWithRfid(sb);
        ///     string s = sb.ToString();
        ///     // 문자열s를구분분석하여활용
        /// }
        /// ```
        ///
        /// ---
        /// </code>
        /// <para>감사 의견(원문과 구분): 본문 StartPrintingWithRfid 및 예제의 BT003Lib.dll/LPWStr/128/int는 부록의 StartPrintWithRfid/BlackfishNfcLib.dll/LPStr/100/void와 다릅니다. 실제 export는 StartPrintWithRfid이며 P/Invoke는 기존 부록 선언을 유지했습니다. 실제 출력 버퍼 크기·문자셋의 안전성은 확인되지 않았습니다.</para>
