        /// <code>
        /// var response = new StringBuilder(100);
        /// BT003CtrlWrapper.StartPrintWithRfid(response);
        /// string resultText = response.ToString();
        /// // 예: "04:03:EA:01:E4:F4:00,00"은 UID와 정상 결과코드의 조합입니다.
        /// // Unknown 또는 00:00:00:00:00:00:00 UID의 의미는 이 함수의 remarks를 확인합니다.
        /// </code>
        /// </example>
        [DllImport("BlackfishNfcLib.dll", CallingConvention = CallingConvention.StdCall)]
        public static extern void StartPrintWithRfid([MarshalAs(UnmanagedType.LPStr, SizeConst = 100)] StringBuilder strReturn);

